package vn.teasmart.backend.auth;
import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.SimpleTransactionStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import vn.teasmart.backend.service.*;
import vn.teasmart.backend.repository.*;
import vn.teasmart.backend.entity.*;
import vn.teasmart.backend.storage.*;
import vn.teasmart.backend.security.*;
import vn.teasmart.backend.exception.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ProfileAndLinkTest {
 private final UserRepository users=mock(UserRepository.class);private final UserService userService=mock(UserService.class);private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
 private User user(){var u=new User();u.setUserId(42L);u.setEmail("fixture@example.invalid");u.setRole("CUSTOMER");u.setStatus("ACTIVE");u.setPasswordHash(encoder.encode("old-test-password"));when(users.findLockedByUserId(42L)).thenReturn(Optional.of(u));when(userService.requireActiveUser(42L)).thenReturn(u);return u;}
 private ProfileService profile(){return new ProfileService(users,userService,encoder,mock(ReviewImageValidator.class),mock(ReviewImageStorage.class));}
 @Test void phoneUniqueRaceReturnsConflict(){user();doThrow(new org.springframework.dao.DataIntegrityViolationException("test unique collision")).when(users).flush();var e=assertThrows(ProfileException.class,()->profile().updatePhone(42L,"0912345678"));assertEquals(409,e.status());}
 @Test void phoneControllerUsesJwtSubjectOnly(){var service=mock(ProfileService.class);var controller=new vn.teasmart.backend.controller.ProfileController(service);var jwt=org.springframework.security.oauth2.jwt.Jwt.withTokenValue("test-only").header("alg","none").subject("42").build();controller.phone(jwt,new vn.teasmart.backend.controller.ProfileController.PhoneRequest("0912345678"));verify(service).updatePhone(42L,"0912345678");}
 @Test void phoneCanonicalizesAndPreservesIdentity(){var u=user();profile().updatePhone(42L," +84 912 345 678 ");assertEquals("0912345678",u.getPhone());assertEquals("fixture@example.invalid",u.getEmail());assertEquals("CUSTOMER",u.getRole());verify(users).flush();}
 @Test void invalidAndDuplicatePhoneCannotMutate(){var u=user();assertThrows(ProfileException.class,()->profile().updatePhone(42L,"0912-345678"));assertNull(u.getPhone());when(users.existsByPhone("0912345678")).thenReturn(true);assertThrows(ProfileException.class,()->profile().updatePhone(42L,"0912345678"));assertNull(u.getPhone());verify(users,never()).flush();}
 @Test void inactivePhoneUpdateDenied(){var u=user();u.setStatus("INACTIVE");assertThrows(org.springframework.security.authentication.BadCredentialsException.class,()->profile().updatePhone(42L,"0912345678"));verify(users,never()).flush();}
 @Test void passwordRequiresCurrentAndPreservesIdentity(){var u=user();profile().changePassword(42L,"old-test-password","new-test-password");assertTrue(encoder.matches("new-test-password",u.getPasswordHash()));assertEquals("CUSTOMER",u.getRole());assertEquals("fixture@example.invalid",u.getEmail());assertEquals(42L,u.getUserId());}
 @Test void wrongPasswordAndGoogleOnlyCannotChangePassword(){var u=user();assertThrows(ProfileException.class,()->profile().changePassword(42L,"wrong","new-test-password"));assertTrue(encoder.matches("old-test-password",u.getPasswordHash()));u.setPasswordHash(null);assertThrows(ProfileException.class,()->profile().changePassword(42L,"wrong","new-test-password"));verify(users,never()).flush();}
 @Test void bcryptByteLimitIsEnforced(){user();assertThrows(ProfileException.class,()->profile().changePassword(42L,"old-test-password","ộ".repeat(30)));}
 @Test void avatarCannotReadUnreferencedReviewFile(){var storage=mock(ReviewImageStorage.class);var p=new ProfileService(users,userService,encoder,mock(ReviewImageValidator.class),storage);assertThrows(ResourceNotFoundException.class,()->p.readAvatar("00000000-0000-0000-0000-000000000000.png"));verifyNoInteractions(storage);}
 @Test void galleryDisabledReadsLegacyWithoutNewTable(){var jdbc=mock(JdbcTemplate.class);var products=mock(ProductRepository.class);var p=new Product();p.setProductId(9L);p.setImageUrl("/demo/tea/ts-demo-001.png");when(products.findById(9L)).thenReturn(Optional.of(p));var gallery=new ProductGalleryService(jdbc,products,mock(ProductService.class),false);assertEquals(1,gallery.get(9L,true).urls().size());assertThrows(ProfileException.class,()->gallery.save(9L,java.util.List.of("/x.png")));verifyNoInteractions(jdbc);}
 @Test void imageUrlsDoNotAcceptScriptsOrCredentials(){assertTrue(ProductGalleryService.validUrl("/demo/tea/x.png"));assertTrue(ProductGalleryService.validUrl("https://example.invalid/x.png"));for(String url:java.util.List.of("javascript:alert(1)","//example.invalid/x.png","https://user:password@example.invalid/x.png","data:image/png,x"))assertFalse(ProductGalleryService.validUrl(url));}
 private GoogleLinkService link(GoogleTokenVerifier verifier,GoogleLoginChallengeStore challenges){var tx=mock(PlatformTransactionManager.class);when(tx.getTransaction(any())).thenReturn(new SimpleTransactionStatus());return new GoogleLinkService(users,userService,encoder,verifier,challenges,mock(JwtService.class),tx);}
 @Test void linkPreservesAccountAndRequiresPasswordPlusVerifiedIdentity(){var u=user();var v=mock(GoogleTokenVerifier.class);var c=mock(GoogleLoginChallengeStore.class);when(c.require("binding")).thenReturn("nonce");when(v.verify("test-token","nonce")).thenReturn(new GoogleTokenVerifier.Identity("test-sub","fixture@example.invalid","Ignored new name"));link(v,c).link(42L,"old-test-password","test-token","binding");assertEquals("test-sub",u.getGoogleSub());assertEquals("CUSTOMER",u.getRole());assertEquals(42L,u.getUserId());verify(c).consume("binding","nonce");verify(users).saveAndFlush(u);}
 @Test void wrongPasswordDoesNotInvokeGoogle(){user();var v=mock(GoogleTokenVerifier.class);var c=mock(GoogleLoginChallengeStore.class);assertThrows(ProfileException.class,()->link(v,c).link(42L,"wrong","test-token","binding"));verifyNoInteractions(v,c);}
 @Test void adminOrMismatchedEmailCannotBeLinked(){var u=user();var v=mock(GoogleTokenVerifier.class);var c=mock(GoogleLoginChallengeStore.class);u.setRole("ADMIN");assertThrows(ProfileException.class,()->link(v,c).link(42L,"old-test-password","test-token","binding"));verifyNoInteractions(v);u.setRole("CUSTOMER");when(c.require("binding")).thenReturn("nonce");when(v.verify(anyString(),anyString())).thenReturn(new GoogleTokenVerifier.Identity("other-sub","different@example.invalid","Ignore"));assertThrows(ProfileException.class,()->link(v,c).link(42L,"old-test-password","test-token","binding"));assertNull(u.getGoogleSub());verify(users,never()).saveAndFlush(any());}
 @Test void profileUpdatesNameAndPhoneWithoutChangingIdentity(){var u=user();var email=u.getEmail();var role=u.getRole();profile().updateProfile(42L,"  New fixture name  ","+84 912 345 678");assertEquals("New fixture name",u.getFullName());assertEquals("0912345678",u.getPhone());assertEquals(email,u.getEmail());assertEquals(role,u.getRole());verify(users).flush();}
 @Test void invalidProfileNameDoesNotWrite(){user();assertThrows(ProfileException.class,()->profile().updateProfile(42L," ","0912345678"));verify(users,never()).flush();}
 @Test void googleLinkStatusNeverExposesIdentityAndDoesNotWrite(){var u=user();var service=link(mock(GoogleTokenVerifier.class),mock(GoogleLoginChallengeStore.class));var initial=service.status(42L);assertFalse(initial.linked());assertTrue(initial.canLink());u.setGoogleSub("test-linked-sub");u.setGoogleEmail("google@example.invalid");u.setPasswordHash(null);var linked=service.status(42L);assertEquals("google@example.invalid",linked.email());assertTrue(linked.linked());assertFalse(linked.canLink());verify(users,never()).saveAndFlush(any());}
 @Test void googleLinkStatusRequiresActiveAccount(){when(userService.requireActiveUser(42L)).thenThrow(new org.springframework.security.authentication.BadCredentialsException("Authentication failed."));assertThrows(org.springframework.security.authentication.BadCredentialsException.class,()->link(mock(GoogleTokenVerifier.class),mock(GoogleLoginChallengeStore.class)).status(42L));}
}
